{"outcome":"component","existing":"","reason":"","code":"QuoteDark","label":"Dark quote","description":"A quote set on a dark background, with the portrait of the person quoted beside it, their name and their role. Use it for a testimonial or a pull quote that should stand out from the page around it.","props":"[{"name":"quote","type":"text","label":"Quote","required":true,"max":400},{"name":"author","type":"text","label":"Author","required":true,"max":80},{"name":"role","type":"text","label":"Role","max":120},{"name":"portrait","type":"image","label":"Portrait","help":"A photo of the person quoted, shown in a circle."},{"name":"tone","type":"choice","label":"Background","choices":{"dark":"Dark","accent":"Accent colour"},"default":"dark"}]","sample":"{"quote":"Depuis que nous travaillons ensemble, nos clientes reçoivent leurs commandes en deux jours au lieu d’une semaine.","author":"Claire Martin","role":"Directrice de l’atelier Fil & Cie","portrait":null,"tone":"dark"}","template":"<section class="quote-dark quote-dark--{{ props.tone|default('dark') }}"><figure class="quote-dark__figure">{% if props.portrait %}<div class="quote-dark__media" data-cms-sizes="(min-width: 48rem) 10rem, 6rem"><img class="quote-dark__portrait" src="{{ props.portrait }}" alt="{{ props.author }}"></div>{% endif %}<div class="quote-dark__body"><blockquote class="quote-dark__text"><p>{{ props.quote }}</p></blockquote><figcaption class="quote-dark__caption"><span class="quote-dark__author">{{ props.author }}</span>{% if props.role is not empty %}<span class="quote-dark__role">{{ props.role }}</span>{% endif %}</figcaption></div></figure></section>","css":".quote-dark__figure { margin: 0; padding: 2rem 1.5rem; border-radius: 0.5rem; display: flex; flex-direction: column; align-items: flex-start; gap: 1.5rem; background: var(--cms-color-text); color: var(--cms-color-on-dark); }
.quote-dark--accent .quote-dark__figure { background: var(--cms-color-accent-strong); color: var(--cms-color-on-accent); }
.quote-dark__media { flex: none; }
.quote-dark__portrait { display: block; width: 6rem; height: 6rem; border-radius: 50%; object-fit: cover; border: 3px solid var(--cms-color-accent); }
.quote-dark--accent .quote-dark__portrait { border-color: var(--cms-color-on-accent); }
.quote-dark__body { min-width: 0; }
.quote-dark__text { margin: 0 0 1.25rem; padding-left: 1rem; border-left: 3px solid var(--cms-color-accent); font-size: 1.375rem; line-height: 1.4; color: inherit; }
.quote-dark--accent .quote-dark__text { border-left-color: var(--cms-color-on-accent); }
.quote-dark__text p { margin: 0; }
.quote-dark__caption { display: flex; flex-direction: column; gap: 0.25rem; }
.quote-dark__author { font-weight: 700; color: inherit; }
.quote-dark__role { color: inherit; opacity: 0.85; }
@media (min-width: 48rem) { .quote-dark__figure { flex-direction: row; align-items: center; gap: 2.5rem; padding: 3rem; } .quote-dark__portrait { width: 10rem; height: 10rem; } .quote-dark__text { font-size: 1.75rem; padding-left: 1.5rem; } }"}
